		{
			DC_Main.RsQry = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject((object)("INSERT INTO ROJ_MEL_DATA(CO_CODE,LC_CODE,CO_YEAR,CO_BOOK,VCH_NO,LEDR_KEY,VCH_DATE,VCH_TYPE,BOOK_NAME,  AC_CODE,LD_CODE,CR_AMT,DR_AMT,AC_NAME,IT_TYPE,SIGN,ITM_PCS,ITM_GWT,ITM_NWT,ITM_TOUCH,ITM_WEST,ITM_FINE,ITM_RATE,ITM_AMT,LBR_RATE,LBR_AMT,OTH_AMT,NET_AMT,  IT_DESC,IT_CODE,MEMB_CODE,SCHM_CODE,REF_NO,DATA_TYPE)  Select A.CO_CODE,A.LC_CODE,A.CO_YEAR,A.CO_BOOK,A.VCH_NO,A.CO_CODE+A.LC_CODE+A.CO_YEAR+A.CO_BOOK+A.VCH_NO+'01'+STR(A.SR_NO),A.VCH_DATE,B.BOOK_SNAME,B.MAIN_BOOK,  D.SALE_AC,A.AC_CODE,A.NET_AMT-(A.LBR_AMT+A.OTH_AMT),0,'',A.IT_TYPE,'-',A.ITM_PCS,A.ITM_GWT,A.ITM_NWT,0,0,0,A.ITM_RATE,A.ITM_AMT,A.LBR_RATE,A.LBR_AMT,A.OTH_AMT,A.NET_AMT,  C.IT_NAME,A.IT_CODE,'','','',B.DATA_TYPE FROM ((((SL_DATA AS F LEFT JOIN SL_DETL AS A ON F.CO_CODE = A.CO_CODE AND F.LC_CODE = A.LC_CODE AND F.CO_YEAR = A.CO_YEAR AND F.CO_BOOK = A.CO_BOOK AND F.VCH_NO = A.VCH_NO) LEFT JOIN BOOK_DETL AS B ON A.CO_CODE = B.CO_CODE AND A.LC_CODE = B.LC_CODE AND A.CO_BOOK = B.CO_BOOK) LEFT JOIN ITEM_MAST AS C ON A.CO_CODE = C.CO_CODE AND A.IT_CODE = C.IT_CODE)  LEFT JOIN  GROUP_MAST AS D ON C.CO_CODE = D.CO_CODE AND C.GR_CODE = D.GR_CODE)LEFT JOIN AC_MAST AS E ON A.CO_CODE = E.CO_CODE AND A.AC_CODE = E.AC_CODE WHERE A.CO_CODE = '" + DC_Main.MCo_code + "' AND A.LC_CODE = '" + DC_Main.MLc_code + "' AND A.CO_YEAR = '" + DC_Main.MCo_year + "' AND A.VCH_DATE >= '" + Strings.Format((object)DC_Main.MOp_dt, "MM/dd/yyyy") + "' AND B.MAIN_BOOK IN ('SALES','B2B SALES') "), Interaction.IIf(Operators.CompareString(MsBook, "", false) == 0, (object)"", (object)(" AND A.CO_BOOK ='" + MsBook + "'"))), Interaction.IIf(Operators.CompareString(MsVchNo, "", false) == 0, (object)"", (object)(" AND A.VCH_NO ='" + MsVchNo + "'"))), (object)" AND B.SR_NO = 1 AND A.NET_AMT <> 0 "));
